package com.team2.wellness.engagement.notification.domain;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="notifications") public class Notification { @Id private UUID id; @Column(name="user_id",nullable=false) private UUID userId; @Column(nullable=false,length=32) private String type; @Column(nullable=false,columnDefinition="text") private String content; @Column(name="created_at",nullable=false) private Instant createdAt; protected Notification(){} public Notification(UUID userId,String type,String content){id=UUID.randomUUID();this.userId=userId;this.type=type;this.content=content;createdAt=Instant.now();} public UUID getId(){return id;} }
